/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
const spec = readFileSync('.pipeline/specs/card-tidy.md', 'utf8');
const sections = [...spec.matchAll(/"'^### ([a-zA-Z_]+)'"\\n([\\s\\S]*?)(?="'^### |''^## |$(?!['"\\s\\S]))/gm)];
assert.equal(sections.length, 17);
const kbPath = 'server/kristy_perimeter_kb.json';
const kbText = readFileSync(kbPath, 'utf8');
const kb = JSON.parse(kbText);
assert.equal(kbText, JSON.stringify(kb, null, 2) + '\\n');
const pinPath = 'server/test/acceptance/twoLinePin.js';
let pinText = readFileSync(pinPath, 'utf8');
const pinMatch = pinText.match(/export const TWO_LINE = (\\{[\\s\\S]*?\\n\\});/);
assert.ok(pinMatch);
const pins = JSON.parse(pinMatch[1]);
assert.equal(pinMatch[1], JSON.stringify(pins, null, 2));
const ids = [];
for (const [,id,section] of sections) {
  const arrays = [...section.matchAll(/"'```json'"\\n([\\s\\S]*?)\\n"'```/g)].map((m) => JSON.parse(m[1]));
  assert.equal(arrays.length, 2, id);
  const entry = kb.entries.find((e) => e.id === id);
  assert.ok(entry && pins[id], id);
  [entry.buying_tips, entry.watch_out] = arrays;
  pins[id].buying_tips = arrays[0];
  if (Object.hasOwn(pins[id], '"'watch_out')) pins[id].watch_out = arrays[1];
  ids.push(id);
}
ids.splice(5, 0, 'pick_canned_tomatoes');
assert.equal(ids.length, 18);
pinText = pinText.replace(pinMatch[0], "'`export const TWO_LINE = ${JSON.stringify(pins, null, 2)};`);
assert.ok(!pinText.includes('"'const TIDIED'));
pinText += '\\n// Card-tidy owns the live copy; historical batches keep the cards as they stood at 8264bd0.\\n';
pinText += "'`const TIDIED = new Set([${ids.map((id) => `'"'"'${id}'"'"'`).join('"', ')}]);\\n"'`;
pinText += "const PRE_TIDY = JSON.parse(execFileSync('"'git', ['show', '8264bd0:server/kristy_perimeter_kb.json'], { cwd: ROOT, maxBuffer: 64 << 20 }).toString());\\n\";
pinText += 'export const preTidy = (e) => (e && TIDIED.has(e.id) ? PRE_TIDY.entries.find((x) => x.id === e.id) : e);\\n';
const updates = new Map([[kbPath, JSON.stringify(kb, null, 2) + '\\n'], [pinPath, pinText]]);
const historical = ['ca-4b', 'ca-7', 'concernAdditives', 'concernBioengineered', 'concernBpa', 'concernSalmon', 'concernShrimp', 'soyMilkRank', 'k6', 'k7', 'k11', 'w2'];
for (const file of historical) {
  const path = "'`server/test/acceptance/${file}.test.js`;
  let source = readFileSync(path, '"'utf8');
  assert.ok("'!source.includes('"'preTidy'), path);
  const importPattern = /"'^import '"\\{ (["'^'"\\n]+) \\} from '\\.\\/twoLinePin\\.js';"'$/m;
  if (importPattern.test(source)) {
    source = source.replace(importPattern, "import { $1, preTidy } from '"'./twoLinePin.js';\");
  } else {
    const imports = [...source.matchAll(/"'^import .+;$/gm)];
    assert.ok(imports.length, path);
    const last = imports.at(-1);
    const end = last.index + last[0].length;
    source = source.slice(0, end) + "'"\\nimport { preTidy } from './twoLinePin.js';\" + source.slice(end);
  }
  const overlay = '\\nkb.entries = kb.entries.map(preTidy);';
  if (['k6', 'k7', 'k11', 'w2'].includes(file)) {
    const last = [...source.matchAll(/"'^import .+;$/gm)].at(-1);
    const end = last.index + last[0].length;
    source = source.slice(0, end) + overlay + source.slice(end);
  } else {
    const load = source.match(/''^const kb = .+;$/m);
    assert.ok(load, path);
    source = source.replace(load[0], load[0] + overlay);
  }
  updates.set(path, source);
}
const k14Path = '"'server/test/acceptance/k14.test.js';
let k14 = readFileSync(k14Path, 'utf8');
const oldReplacement = '        \"import { assertPassRule } from \\'./passRule.js\\';\\\\nimport { beforeConcern } from \\'./twoLinePin.js\\';\")';
assert.equal(k14.split(oldReplacement).length, 2);
const newReplacement = [
  \"        ['k6', 'k7', 'k11'].includes(file)\",
  '          ? \"import { assertPassRule } from \\'./passRule.js\\';\\\\nimport { beforeConcern, preTidy } from \\'./twoLinePin.js\\';\\\\nkb.entries = kb.entries.map(preTidy);\"',
  '          : \"import { assertPassRule } from \\'./passRule.js\\';\\\\nimport { beforeConcern } from \\'./twoLinePin.js\\';\")',
].join('\\n');
k14 = k14.replace(oldReplacement, newReplacement);
updates.set(k14Path, k14);
assert.equal(updates.size, 15);
for (const [path, content] of updates) writeFileSync(path, content, 'utf8');
console.log('Applied exact spec arrays to 17 cards, updated existing pins, and added historical overlays in 15 owned files.');
NODE"

